import { isTfExpr, scopedLabelToBagKey, tfLabelToTsLabel } from "../../engine/tf/index.js";
import { SUB_TYPE_BY_RESOURCE as FIELD_SUB_TYPE_BY_RESOURCE } from "../field/types.js";
export function resolveToolFieldKey(fieldRef, scopeTfLabel, scope = "app", ctx) {
    if (fieldRef === undefined)
        return undefined;
    if (isTfExpr(fieldRef) && fieldRef.$expr === "resource-attr" && FIELD_SUB_TYPE_BY_RESOURCE.has(fieldRef.type)) {
        return scopedLabelToBagKey(scopeTfLabel, fieldRef.label, scope);
    }
    if (isTfExpr(fieldRef) && fieldRef.$expr === "data-attr" && fieldRef.type === "elementum_field") {
        const fieldAttrs = ctx?.dataAttrs?.("elementum_field", fieldRef.label);
        const objectId = fieldAttrs?.object_id;
        const ownerType = scope === "element" ? "elementum_element" : "elementum_app";
        const addressesResolvedToSameTarget = objectId !== undefined && isTfExpr(objectId) && objectId.$expr === "data-attr" &&
            objectId.type === ownerType && objectId.label === scopeTfLabel && objectId.path.join(".") === "id";
        if (addressesResolvedToSameTarget) {
            const refOnlyField = ctx?.foreignFieldRefsByDataAddress?.get(`elementum_field.${fieldRef.label}`);
            if (refOnlyField !== undefined)
                return refOnlyField.fieldKey;
        }
        // The reverse of `agent-tool`/`skill-tool` to-tf's
        // `foreignTargetFieldRefValue`: a CUSTOM field on the tool's target
        // aspect, resolved via a `data.elementum_field` lookup rather than a
        // resource block (the target isn't recursively exported, so it has no
        // field resource of its own in this stream). `scopeTfLabel`/`scope`
        // already identify the RESOLVED target (see this module's header
        // comment), so the label prefix to strip is known without any extra
        // lookup — mirrors `crossAppFieldToTf`'s label construction in
        // `automation/to-tf.ts`.
        const prefix = `${scope}_${scopeTfLabel}_`;
        if (fieldRef.label.startsWith(prefix)) {
            return tfLabelToTsLabel(fieldRef.label.slice(prefix.length));
        }
    }
    if (isTfExpr(fieldRef) && fieldRef.$expr === "local") {
        const prefix = `${scopeTfLabel}_`;
        if (fieldRef.name.startsWith(prefix) && fieldRef.name.endsWith("_field_id")) {
            return tfLabelToTsLabel(fieldRef.name.slice(prefix.length, -"_field_id".length));
        }
    }
    return undefined;
}
